<div class="page-head"><div><h1>Obrigações fiscais</h1><p>Controle os prazos e a situação de cada obrigação.</p></div><a class="btn" href="/obrigacoes/nova">+ Nova obrigação</a></div>
<form class="filters" method="get"><input name="q" placeholder="Buscar obrigação ou cliente" value="<?=e($q)?>"><select name="status"><option value="">Todos os status</option><?php foreach(['Pendente','Em andamento','Concluída'] as $s):?><option <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn">Filtrar</button><a class="btn secondary" href="/obrigacoes">Limpar</a></form>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Obrigação</th><th>Cliente</th><th>Vencimento</th><th>Status</th><th>Alerta</th><th>Ações</th></tr></thead><tbody>
<?php foreach($items as $o):$late=$o['status']!=='Concluída'&&$o['vencimento']<date('Y-m-d');?><tr><td><?=e($o['titulo'])?></td><td><?=e($o['cliente_nome'])?></td><td><?=date('d/m/Y',strtotime($o['vencimento']))?></td><td><span class="tag"><?=e($o['status'])?></span></td><td class="<?=$late?'late':'ok'?>"><?=$late?'Vencida':(strtotime($o['vencimento'])-strtotime(date('Y-m-d'))<=259200?'Prazo próximo':'Em dia')?></td><td class="actions"><a href="/obrigacoes/editar?id=<?=$o['id']?>">Editar</a><form method="post" action="/obrigacoes/excluir" onsubmit="return confirm('Excluir esta obrigação?');"><?=csrf_field()?><input type="hidden" name="id" value="<?=$o['id']?>"><button class="link">Excluir</button></form></td></tr><?php endforeach;?>
<?php if(!$items):?><tr><td colspan="6">Nenhuma obrigação encontrada.</td></tr><?php endif;?></tbody></table></div><div class="pagination"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'active':''?>" href="<?=e(page_url(['page'=>$i]))?>"><?=$i?></a><?php endfor;?></div></section>